css:
.note-to-mp {box-sizing:border-box;max-width:640px;margin:0 auto;padding:18px 20px 40px;background:#FFFFFF;color:#30383D;font-family:-apple-system,BlinkMacSystemFont,'PingFang SC','Microsoft YaHei',Arial,sans-serif;font-size:16px;line-height:1.9!important;word-break:break-word;overflow-wrap:break-word;}
.note-to-mp * {box-sizing:border-box;}
.note-to-mp p {margin:0 0 22px!important;font-size:16px;line-height:1.9!important;letter-spacing:.03em;text-align:justify!important;}
.note-to-mp h1 {margin:0 0 28px;font-size:24px;font-weight:700;line-height:1.5!important;word-break:break-word;}
.note-to-mp h2 {margin:44px 0 22px!important;font-size:20px;font-weight:700;line-height:1.5!important;}
.note-to-mp h3 {margin:28px 0 16px!important;font-size:17px;font-weight:700;line-height:1.55!important;}
.note-to-mp h4,.note-to-mp h5,.note-to-mp h6 {margin:24px 0 12px!important;font-size:16px;font-weight:700;line-height:1.55!important;}
.note-to-mp strong {font-weight:700;}
.note-to-mp em {font-style:italic;}
.note-to-mp a {text-decoration:none;border-bottom:1px solid currentColor;}
.note-to-mp blockquote {margin:28px 0!important;padding:20px;}
.note-to-mp blockquote p {margin:0!important;font-size:15px;line-height:1.85!important;text-align:inherit!important;}
.note-to-mp ul,.note-to-mp ol {margin:0 0 24px;padding:0 0 0 25px;line-height:1.85!important;}
.note-to-mp li {margin:10px 0;padding-left:3px;font-size:16px;line-height:1.85!important;}
.note-to-mp code {padding:2px 5px;border-radius:3px;background:#F1F4F5;color:#34474F;font-family:Menlo,Monaco,Consolas,monospace;font-size:14px;white-space:normal;overflow-wrap:anywhere;}
.note-to-mp .code-section {margin:24px 0;overflow:hidden;border:1px solid #DFE5E8;background:#F6F8F9;border-radius:4px;}
.note-to-mp .code-section pre {margin:0;padding:16px;white-space:pre-wrap!important;word-break:break-all!important;}
.note-to-mp .code-section code {display:block;padding:0;background:transparent;border:none;font-size:13px;line-height:1.7!important;}
.note-to-mp img {display:block;width:100%;max-width:100%;height:auto;margin:28px auto;border:0;}
.note-to-mp hr {height:0;border:0;border-top:1px solid #DFE5E8;margin:40px 0;}
.note-to-mp table {width:100%;table-layout:fixed;box-sizing:border-box;margin:24px 0;border-collapse:collapse;border-spacing:0;font-family:-apple-system,BlinkMacSystemFont,'PingFang SC','Microsoft YaHei',Arial,sans-serif;font-size:13px;line-height:1.7!important;}
.note-to-mp th,.note-to-mp td {box-sizing:border-box;padding:10px 9px;text-align:left;vertical-align:top;white-space:normal;word-break:break-word;overflow-wrap:anywhere;border-bottom:1px solid #E1E5E7;}
.note-to-mp th {font-weight:700;}

.note-to-mp {max-width:686px;padding:18px 18px 42px;color:#2F3437;line-height:1.78!important;}
.note-to-mp p {line-height:1.78!important;letter-spacing:.01em;margin-bottom:18px!important;}
.note-to-mp h1 {padding:0 0 18px;background:#FFFFFF;color:#245A64;border-bottom:2px solid #86B6BB;font-size:24px;font-weight:700;line-height:1.45!important;letter-spacing:0;}
.note-to-mp h2 {margin:40px 0 19px!important;padding:0;color:#2F3437;font-size:20px;font-weight:700;line-height:1.55!important;}
.note-to-mp .wechatpb-heading-label {display:block;padding:0;margin:0 0 7px;color:#286C78;font-family:Menlo,Consolas,monospace;font-size:18px;font-weight:500;line-height:1.3!important;letter-spacing:.03em;}
.note-to-mp h3 {margin:25px 0 14px!important;color:#245A64;font-size:17px;border:0;padding:0;}
.note-to-mp h4,.note-to-mp h5,.note-to-mp h6 {color:#245A64;margin:22px 0 12px!important;}
.note-to-mp strong {color:#245A64;background:#EEF6F6;padding:1px 3px;}
.note-to-mp em,.note-to-mp a {color:#245A64;}
.note-to-mp blockquote {padding:20px 18px;border:0;border-radius:2px;background:#245A64;color:#FFFFFF;}
.note-to-mp blockquote p {font-size:16px;line-height:1.8!important;color:#FFFFFF;}
.note-to-mp blockquote strong {color:#FFFFFF;background:transparent;padding:0;}
.note-to-mp blockquote a,.note-to-mp blockquote em,.note-to-mp blockquote code {color:#FFFFFF;background:transparent;}
.note-to-mp ul {list-style-type:square;padding:0 0 0 24px;}
.note-to-mp ol {list-style-type:decimal-leading-zero;padding-left:32px;}
.note-to-mp li {padding-bottom:9px;border-bottom:1px solid #DAE8E9;margin:9px 0;font-size:16px;line-height:1.78!important;}
.note-to-mp li::marker {color:#286C78;font-weight:700;}
.note-to-mp img {border:0;border-radius:0;margin:23px auto;}
.note-to-mp hr {border-top:1px solid #86B6BB;margin:34px 0;}
.note-to-mp code {background:#EEF6F6;color:#245A64;border:1px solid #D7E7E9;border-radius:2px;}
.note-to-mp .code-section {background:#F4F8F8;border:1px solid #D7E7E9;border-left:3px solid #286C78;border-radius:0;}
.note-to-mp .code-section code {color:#245A64;}
.note-to-mp th {color:#245A64;background:#FFFFFF;border-top:2px solid #286C78;border-bottom:1px solid #86B6BB;}
.note-to-mp td {color:#2F3437;background:#FFFFFF;border-bottom:1px solid #D7E7E9;}
.note-to-mp tr:nth-child(odd) td {background:#EEF6F6;}
